class Qwen2_5_VLForConditionalGenerationPruning(Qwen2_5_VLForConditionalGeneration):

    def __init__(self, config, pruning_method='vanilla', visual_token_num=-1):
        super().__init__(config)
        if pruning_method == 'fastv':
            self.model = FastVQwen2_5_VLModel(config, visual_token_num)
        elif pruning_method == 'sparsevlm':
            # TODO: Implement SparseVLM
            raise NotImplementedError("SparseVLM is not yet implemented for Qwen2.5-VL")
            # self.model = SparseVLMQwen2_5_VLModel(config, visual_token_num)
        elif pruning_method == 'tops_variant3':
            self.model = TOPSVariant3Qwen2_5_VLModel(config, visual_token_num)
        else:
            self.model = Qwen2_5_VLModel(config)

        self.pruning_method = pruning_method
        self.target_visual_token_num = visual_token_num  # Original target (never changes)
        self.visual_token_num = visual_token_num  # Runtime metric (gets updated by TOPS-Variant3/FastV)

    def forward(
        self,
        input_ids: Optional[torch.LongTensor] = None,
        attention_mask: Optional[torch.Tensor] = None,
        position_ids: Optional[torch.LongTensor] = None,
        past_key_values: Optional[List[torch.FloatTensor]] = None,
        inputs_embeds: Optional[torch.FloatTensor] = None,
        labels: Optional[torch.LongTensor] = None,
        use_cache: Optional[bool] = None,
        output_attentions: Optional[bool] = None,
        output_hidden_states: Optional[bool] = None,
        return_dict: Optional[bool] = None,
        pixel_values: Optional[torch.Tensor] = None,
        pixel_values_videos: Optional[torch.FloatTensor] = None,
        image_grid_thw: Optional[torch.LongTensor] = None,
        video_grid_thw: Optional[torch.LongTensor] = None,
        rope_deltas: Optional[torch.LongTensor] = None,
        cache_position: Optional[torch.LongTensor] = None,
        second_per_grid_ts: Optional[torch.Tensor] = None,
    ) -> Union[Tuple, Qwen2_5_VLCausalLMOutputWithPast]:
        r"""
            labels (`torch.LongTensor` of shape `(batch_size, sequence_length)`, *optional*):
                Labels for computing the masked language modeling loss. Indices should either be in `[0, ...,
                config.vocab_size]` or -100 (see `input_ids` docstring). Tokens with indices set to `-100` are ignored
                (masked), the loss is only computed for the tokens with labels in `[0, ..., config.vocab_size]`.

        Returns:

        Example:

        ```python
        >>> from PIL import Image
        >>> import requests
        >>> from transformers import AutoProcessor, Qwen2_5_VLForConditionalGeneration

        >>> model = Qwen2_5_VLForConditionalGeneration.from_pretrained("Qwen/Qwen2.5-VL-7B-Instruct")
        >>> processor = AutoProcessor.from_pretrained("Qwen/Qwen2.5-VL-7B-Instruct")

        >>> messages = [
            {
                "role": "user",
                "content": [
                    {"type": "image"},
                    {"type": "text", "text": "What is shown in this image?"},
                ],
            },
        ]
        >>> url = "https://www.ilankelman.org/stopsigns/australia.jpg"
        >>> image = Image.open(requests.get(url, stream=True).raw)

        >>> text = processor.apply_chat_template(messages, tokenize=False, add_generation_prompt=True)
        >>> inputs = processor(text=[text], images=[image], vision_infos=[vision_infos])

        >>> # Generate
        >>> generate_ids = model.generate(inputs.input_ids, max_length=30)
        >>> tokenizer.batch_decode(generate_ids, skip_special_tokens=True, clean_up_tokenization_spaces=False)[0]
        "The image shows a street scene with a red stop sign in the foreground. In the background, there is a large red gate with Chinese characters ..."
        ```"""

        output_attentions = output_attentions if output_attentions is not None else self.config.output_attentions
        output_hidden_states = (
            output_hidden_states if output_hidden_states is not None else self.config.output_hidden_states
        )
        return_dict = return_dict if return_dict is not None else self.config.use_return_dict

        if inputs_embeds is None:
            inputs_embeds = self.model.embed_tokens(input_ids)
            if pixel_values is not None:
                pixel_values = pixel_values.type(self.visual.dtype)

                if self.pruning_method in ['fastervlm', 'prumerge', 'prumerge+', 'visionzip', 'visionzip+', 'vispruner']:
                    def forward_with_attn(
                        self,
                        hidden_states: torch.Tensor,
                        cu_seqlens: torch.Tensor,
                        rotary_pos_emb: Optional[torch.Tensor] = None,
                        position_embeddings: Optional[Tuple[torch.Tensor, torch.Tensor]] = None,
                    ) -> torch.Tensor:
                        # Memory debug: Start of attention forward
                        if MEMORY_DEBUG_ENABLED:
                            log_memory_stats("Attention Forward: Start", verbose=True)
                            log_tensor_info(hidden_states, "Input hidden_states")

                        seq_length = hidden_states.shape[0]
                        q, k, v = self.qkv(hidden_states).reshape(seq_length, 3, self.num_heads, -1).permute(1, 0, 2, 3).unbind(0)

                        # Memory debug: After QKV projection
                        if MEMORY_DEBUG_ENABLED:
                            log_memory_stats("Attention Forward: After QKV projection", verbose=True)
                            print(f"  Q shape: {q.shape}, K shape: {k.shape}, V shape: {v.shape}")
                            print(f"  Dtype: {q.dtype}")

                        if position_embeddings is None:
                            logger.warning_once(
                                "The attention layers in this model are transitioning from computing the RoPE embeddings internally "
                                "through `rotary_pos_emb` (2D tensor of RoPE theta values), to using externally computed "
                                "`position_embeddings` (Tuple of tensors, containing cos and sin). In v4.54 `rotary_pos_emb` will be "
                                "removed and `position_embeddings` will be mandatory."
                            )
                            emb = torch.cat((rotary_pos_emb, rotary_pos_emb), dim=-1)
                            cos = emb.cos()
                            sin = emb.sin()
                        else:
                            cos, sin = position_embeddings
                        self.q, self.k = q.clone(), k.clone()
                        q, k = apply_rotary_pos_emb_flashatt(q.unsqueeze(0), k.unsqueeze(0), cos, sin)
                        q = q.squeeze(0)
                        k = k.squeeze(0)

                        max_seqlen = (cu_seqlens[1:] - cu_seqlens[:-1]).max().item()
                        attn_output = flash_attn_varlen_func(q, k, v, cu_seqlens, cu_seqlens, max_seqlen, max_seqlen).reshape(
                            seq_length, -1
                        )
                        attn_output = self.proj(attn_output)

                        # Memory debug: Before standard attention computation (for pruning methods)
                        if MEMORY_DEBUG_ENABLED:
                            log_memory_stats("Attention Forward: Before standard attention weights", verbose=True)

                        q, k = apply_rotary_pos_emb_vision(self.q, self.k, cos, sin)
                        q = q.transpose(0, 1)
                        k = k.transpose(0, 1)

                        # Memory debug: Validate attention memory requirements
                        seq_len = q.shape[1]

                        if MEMORY_DEBUG_ENABLED:
                            print(f"\n!!! Computing attention weights for pruning !!!")
                            print(f"  Q shape after transpose: {q.shape}")
                            print(f"  K shape after transpose: {k.shape}")
                            print(f"  Sequence length: {seq_len}")
                            estimated_gb = validate_attention_memory(q.shape, k.shape, dtype=q.dtype, location="VisionZip Attention")

                        # Check if this is a multi-image sequence (e.g., consecutive images in HallusionBench)
                        SINGLE_IMAGE_TOKENS = 1296  # Standard Qwen2.5-VL tokens per image (36x36 grid)
                        MAX_SEQ_LEN_FOR_FULL_ATTENTION = 5000  # GPU memory limit

                        # Detect number of images by floor division (some images may have 1330+ tokens)
                        estimated_num_images = seq_len // SINGLE_IMAGE_TOKENS
                        if estimated_num_images == 0:
                            estimated_num_images = 1

                        tokens_per_image = seq_len / estimated_num_images

                        # Check if the division makes sense (tokens per image should be reasonable)
                        is_likely_multi_image = (
                            estimated_num_images > 1 and
                            800 < tokens_per_image < 2000  # Reasonable range for image tokens
                        )

                        if is_likely_multi_image:
                            print(f"\n📸 Detected multi-image sequence: {estimated_num_images} images")
                            print(f"  Sequence length: {seq_len} tokens")
                            print(f"  Estimated tokens per image: {tokens_per_image:.1f}")

                        if seq_len > MAX_SEQ_LEN_FOR_FULL_ATTENTION:
                            print(f"\n⚠️  WARNING: Sequence length {seq_len} exceeds maximum {MAX_SEQ_LEN_FOR_FULL_ATTENTION}")

                            # For multi-image sequences, use per-image attention
                            if is_likely_multi_image:
                                print(f"  Processing as {estimated_num_images} separate images to avoid OOM")

                                # Calculate actual tokens per image for this sequence
                                actual_tokens_per_img = seq_len // estimated_num_images
                                remainder = seq_len % estimated_num_images

                                # Process each image independently and aggregate
                                all_attn_weights = []
                                for img_idx in range(estimated_num_images):
                                    # Distribute remainder tokens across first few images
                                    start = img_idx * actual_tokens_per_img + min(img_idx, remainder)
                                    end = start + actual_tokens_per_img + (1 if img_idx < remainder else 0)

                                    if end > start:
                                        q_img = q[:, start:end, :]
                                        k_img = k[:, start:end, :]

                                        # Compute attention for this image only
                                        attn_img = torch.matmul(q_img, k_img.transpose(1, 2)) / math.sqrt(q.shape[-1])
                                        attn_img = torch.nn.functional.softmax(attn_img, dim=-1)
                                        all_attn_weights.append(attn_img)

                                # Instead of creating full block-diagonal matrix, store individual blocks
                                # and create a compressed representation for pruning selection
                                # This avoids allocating the full 65136×65136 matrix

                                print(f"  Creating compressed attention representation for {len(all_attn_weights)} images")

                                # For pruning purposes, we need to aggregate attention across images
                                # Option 1: Average attention patterns across all images
                                # Option 2: Keep max attention values across all images
                                # Option 3: Store blocks separately and process during pruning

                                # Using Option 1: Average attention patterns (most memory efficient)
                                # Each image has roughly the same number of tokens, so we can average
                                num_heads = all_attn_weights[0].shape[0]

                                # Find the maximum dimension among all attention blocks
                                max_dim = max(w.shape[-1] for w in all_attn_weights)

                                # Create averaged attention pattern
                                avg_attn = torch.zeros(num_heads, max_dim, max_dim, device=q.device, dtype=q.dtype)

                                for attn_block in all_attn_weights:
                                    block_size = attn_block.shape[-1]
                                    avg_attn[:, :block_size, :block_size] += attn_block

                                avg_attn = avg_attn / len(all_attn_weights)

                                # Store the averaged pattern - this will be used for pruning decisions
                                # The actual attention computation in forward pass will still handle images separately
                                self.attn_weights = avg_attn

                                # Also store the individual blocks for later use if needed
                                self.attn_blocks = all_attn_weights
                                self.num_images = estimated_num_images

                                print(f"  Compressed attention: {avg_attn.shape} (from {seq_len}×{seq_len})")
                                print(f"  Memory saved: ~{(seq_len * seq_len - max_dim * max_dim) * 2 / 1024**3:.2f} GB")

                            else:
                                # Fallback: Use lightweight probe for non-standard sequences
                                print(f"  Using lightweight attention probe for non-standard sequence")
                                q_probe = q.mean(dim=1, keepdim=True)
                                attn_scores = torch.matmul(q_probe, k.transpose(1, 2)) / math.sqrt(q.shape[-1])
                                attn_weights = torch.nn.functional.softmax(attn_scores, dim=-1)
                                self.attn_weights = attn_weights.expand(-1, seq_len, -1)

                            if MEMORY_DEBUG_ENABLED:
                                log_memory_stats("After multi-image attention computation", verbose=True)
                        else:
                            if MEMORY_DEBUG_ENABLED:
                                print(f"  Attempting to allocate full attention matrix...")

                            try:
                                attn_weights = torch.matmul(q, k.transpose(1, 2)) / math.sqrt(q.shape[-1])

                                # Memory debug: After attention matmul
                                if MEMORY_DEBUG_ENABLED:
                                    log_memory_stats("Attention Forward: After attention matmul", verbose=True)
                                    log_tensor_info(attn_weights, "Attention weights matrix")

                                attn_weights = torch.nn.functional.softmax(attn_weights, dim=-1)
                                self.attn_weights = attn_weights

                            except torch.cuda.OutOfMemoryError as e:
                                if MEMORY_DEBUG_ENABLED:
                                    print(f"\n{'!'*70}")
                                    print(f"!!! OOM at attention weight computation !!!")
                                    print(f"{'!'*70}")
                                    print(f"  Tried to compute: {q.shape} @ {k.shape}.T")
                                    print(f"  Expected shape: [{q.shape[0]}, {q.shape[1]}, {k.shape[1]}]")
                                    log_memory_stats("OOM Details", show_tensors=True, verbose=True)
                                raise e

                        return attn_output
                    self.visual.blocks[-1].attn.forward = types.MethodType(forward_with_attn, self.visual.blocks[-1].attn)

                image_embeds = self.visual(pixel_values, grid_thw=image_grid_thw)

                if self.pruning_method in ['fastervlm', 'vispruner']:
                    attn_weights = self.visual.blocks[-1].attn.attn_weights

                    seq_length = pixel_values.shape[0]
                    window_index, _ = self.visual.get_window_index(image_grid_thw)
                    reverse_indices = torch.argsort(window_index)
                    image_attns = attn_weights.view(-1, seq_length // 4, 4, seq_length // 4, 4).mean(dim=(2, 4))
                    image_attns = image_attns[:, reverse_indices, :][:, :, reverse_indices]
                elif self.pruning_method in ['prumerge', 'prumerge+', 'visionzip', 'visionzip+']:
                    attn_keys = self.visual.blocks[-1].attn.k
                    attn_weights = self.visual.blocks[-1].attn.attn_weights

                    # Check if we have multi-image compressed representation
                    if hasattr(self.visual.blocks[-1].attn, 'num_images') and self.visual.blocks[-1].attn.num_images > 1:
                        # For multi-image sequences, we have averaged attention pattern
                        # Process it as if it's for a single image of that size
                        print(f"  Processing compressed multi-image attention for pruning")
                        avg_seq_length = attn_weights.shape[-1]

                        # The averaged attention already represents the typical pattern
                        # We can use it directly for pruning decisions
                        if avg_seq_length % 4 == 0:
                            image_attns = attn_weights.view(-1, avg_seq_length // 4, 4, avg_seq_length // 4, 4).mean(dim=(2, 4))
                        else:
                            # Fallback if dimensions don't align perfectly
                            image_attns = attn_weights

                        # For keys, we also need to handle the multi-image case
                        # Use the first portion of keys as representative
                        if attn_keys.shape[0] > avg_seq_length:
                            attn_keys_subset = attn_keys[:avg_seq_length, :, :]
                        else:
                            attn_keys_subset = attn_keys

                        if attn_keys_subset.shape[0] % 4 == 0:
                            image_keys = attn_keys_subset.view(attn_keys_subset.shape[0] // 4, 4, attn_keys_subset.shape[1], attn_keys_subset.shape[2]).mean(dim=1)
                        else:
                            # Fallback: use stride sampling
                            image_keys = attn_keys_subset[::4, :, :]
                    else:
                        # Standard single-image or manageable sequence processing
                        seq_length = pixel_values.shape[0]
                        window_index, _ = self.visual.get_window_index(image_grid_thw)
                        reverse_indices = torch.argsort(window_index)
                        image_attns = attn_weights.view(-1, seq_length // 4, 4, seq_length // 4, 4).mean(dim=(2, 4))
                        image_attns = image_attns[:, reverse_indices, :][:, :, reverse_indices]
                        image_keys = attn_keys.view(seq_length // 4, 4, attn_keys.shape[1], attn_keys.shape[2]).mean(dim=1)
                        image_keys = image_keys[reverse_indices, :, :]
                elif self.pruning_method in ['trim_mean', 'trim_max', 'cdpruner_mean', 'cdpruner_max']:
                    image_token_indices = torch.where(input_ids == self.config.image_token_id)[1]

                # Generate selection mask
                N, D = image_embeds.shape
                device = image_embeds.device
                selected_masks = torch.ones(N, dtype=torch.bool, device=device)

                if self.pruning_method == 'random':
                    random_scores = torch.rand(N).to(device)
                    selected_indices = random_scores.topk(self.target_visual_token_num, dim=-1).indices

                    selected_masks = torch.zeros(N, dtype=torch.bool, device=device)
                    selected_masks[selected_indices] = True
                elif self.pruning_method == 'fastervlm':
                    image_attns = image_attns.mean(dim=1).mean(dim=0)
                    selected_indices = image_attns.topk(self.target_visual_token_num, dim=-1).indices

                    selected_masks = torch.zeros(N, dtype=torch.bool, device=device)
                    selected_masks[selected_indices] = True
                elif self.pruning_method == 'prumerge' or self.pruning_method == 'prumerge+':
                    image_keys = image_keys.mean(dim=1)
                    image_attns = image_attns.mean(dim=1).mean(dim=0)

                    if self.pruning_method == 'prumerge':
                        selected_indices = image_attns.topk(self.target_visual_token_num, dim=-1).indices
                    elif self.pruning_method == 'prumerge+':
                        arithmetic_step = int(N / self.target_visual_token_num * 2)
                        arithmetic_indices = torch.linspace(arithmetic_step//2, N-1-arithmetic_step//2,
                                                            self.target_visual_token_num//2, dtype=torch.long, device=device)
                        image_attns[arithmetic_indices] = 0
                        selected_indices = image_attns.topk(self.target_visual_token_num//2, dim=-1).indices
                        selected_indices = torch.cat([selected_indices, arithmetic_indices])

                    selected_masks = torch.zeros(N, dtype=torch.bool, device=device)
                    selected_masks[selected_indices] = True
                    pruned_indices = selected_masks.float().topk(N-self.target_visual_token_num, dim=-1, largest=False).indices

                    selected_embeds = image_embeds[selected_indices]
                    selected_keys = image_keys[selected_indices]
                    selected_attns = image_attns[selected_indices]
                    pruned_embeds = image_embeds[pruned_indices]
                    pruned_keys = image_keys[pruned_indices]
                    pruned_attns = image_attns[pruned_indices]

                    selected_keys_norm = selected_keys / selected_keys.norm(dim=-1, keepdim=True)
                    pruned_keys_norm = pruned_keys / pruned_keys.norm(dim=-1, keepdim=True)

                    updated_embeds = torch.zeros_like(selected_embeds)
                    for i in range(updated_embeds.shape[0]):
                        center_key_norm = selected_keys_norm[i]
                        other_keys_norm = torch.cat([
                            selected_keys_norm[:i],
                            selected_keys_norm[i+1:],
                            pruned_keys_norm])

                        similarity = torch.matmul(center_key_norm, other_keys_norm.t())
                        cluster_indices = similarity.topk(32, dim=-1).indices

                        other_embeds = torch.cat([
                            selected_embeds[:i],
                            selected_embeds[i+1:],
                            pruned_embeds])
                        other_attns = torch.cat([
                            selected_attns[:i],
                            selected_attns[i+1:],
                            pruned_attns])

                        cluster_embeds = other_embeds[cluster_indices]
                        cluster_weights = other_attns[cluster_indices].unsqueeze(-1)

                        cluster_avg = torch.sum(cluster_embeds * cluster_weights, dim=0)
                        cluster_center = selected_embeds[i] + cluster_avg
                        updated_embeds[i] = cluster_center
                    image_embeds[selected_indices] = updated_embeds
                elif self.pruning_method == 'visionzip' or self.pruning_method == 'visionzip+':
                    # Memory debug: Start of VisionZip processing
                    if MEMORY_DEBUG_ENABLED:
                        log_memory_stats("VisionZip: Start", verbose=True)
                        print(f"  Image embeds shape: {image_embeds.shape}")
                        print(f"  Target visual tokens: {self.target_visual_token_num}")
                        print(f"  Total tokens N: {N}")

                    if self.pruning_method == 'visionzip':
                        dominant_token_num = int(self.target_visual_token_num * 27 / 32)
                        contextual_token_num = self.target_visual_token_num - dominant_token_num
                    elif self.pruning_method == 'visionzip+':
                        contextual_token_num = int(N * 5 / 100)
                        dominant_token_num = self.target_visual_token_num - contextual_token_num

                    # Ensure at least some dominant tokens
                    dominant_token_num = max(1, min(dominant_token_num, N))
                    contextual_token_num = max(0, min(contextual_token_num, N - dominant_token_num))

                    if MEMORY_DEBUG_ENABLED:
                        print(f"  Dominant tokens: {dominant_token_num}")
                        print(f"  Contextual tokens: {contextual_token_num}")

                    # Memory debug: Before dominant selection
                    if MEMORY_DEBUG_ENABLED:
                        log_memory_stats("VisionZip: Before dominant selection", verbose=True)
                        print(f"  Image_attns shape before reduction: {image_attns.shape}")

                    image_attns = image_attns.mean(dim=1).mean(dim=0)

                    if MEMORY_DEBUG_ENABLED:
                        print(f"  Image_attns shape after reduction: {image_attns.shape}")
                        print(f"  Image_embeds N: {N}")
                        print(f"  Dominant_token_num: {dominant_token_num}")

                    dominant_indices = image_attns.topk(dominant_token_num, dim=-1).indices

                    # Validate indices are within bounds
                    if MEMORY_DEBUG_ENABLED:
                        print(f"  Dominant_indices shape: {dominant_indices.shape}")
                        print(f"  Dominant_indices max: {dominant_indices.max()}")
                        print(f"  Dominant_indices min: {dominant_indices.min()}")

                    # Safety check: ensure indices are within valid range
                    if dominant_indices.max() >= N:
                        print(f"  WARNING: Index out of bounds detected!")
                        print(f"    Max index: {dominant_indices.max()}, but N={N}")
                        print(f"    Image_attns size: {image_attns.shape[0]}")
                        print(f"    Clamping indices to [0, {N-1}]")
                        dominant_indices = torch.clamp(dominant_indices, 0, N - 1)

                    selected_masks = torch.zeros(N, dtype=torch.bool, device=device)
                    selected_masks[dominant_indices] = True

                    # Memory debug: After dominant selection
                    if MEMORY_DEBUG_ENABLED:
                        log_memory_stats("VisionZip: After dominant selection", verbose=True)
                        print(f"  Selected {dominant_indices.shape[0]} dominant tokens")

                    # If no contextual tokens needed, skip merging
                    if contextual_token_num == 0:
                        if MEMORY_DEBUG_ENABLED:
                            print(f"  No contextual tokens needed, skipping merge")
                    else:
                        # Re-verify N matches current image_embeds (in case of modifications)
                        actual_N = image_embeds.shape[0]
                        if actual_N != N:
                            print(f"  WARNING: image_embeds shape changed!")
                            print(f"    Original N: {N}")
                            print(f"    Current N: {actual_N}")
                            print(f"    Recreating selected_masks with correct size")
                            # Recreate selected_masks with correct size
                            old_mask = selected_masks
                            selected_masks = torch.zeros(actual_N, dtype=torch.bool, device=device)
                            # Copy over the valid indices
                            copy_len = min(old_mask.shape[0], actual_N)
                            selected_masks[:copy_len] = old_mask[:copy_len]
                            N = actual_N

                        # Validate selected_masks shape before filtering
                        if MEMORY_DEBUG_ENABLED:
                            print(f"  Selected_masks shape: {selected_masks.shape}")
                            print(f"  Selected_masks sum (selected tokens): {selected_masks.sum()}")
                            print(f"  Image_embeds shape: {image_embeds.shape}")

                        # Safety check: ensure mask and embeddings have matching dimensions
                        if selected_masks.shape[0] != image_embeds.shape[0]:
                            print(f"  ERROR: Shape mismatch!")
                            print(f"    selected_masks length: {selected_masks.shape[0]}")
                            print(f"    image_embeds length: {image_embeds.shape[0]}")
                            raise RuntimeError(f"VisionZip mask shape {selected_masks.shape[0]} doesn't match embeds shape {image_embeds.shape[0]}")

                        # Use image_embeds for filtering (not downsampled image_keys)
                        # This matches InternVL3 implementation
                        filtered_embeds = image_embeds[~selected_masks]

                        # Check if we have any filtered embeddings
                        if filtered_embeds.shape[0] == 0:
                            if MEMORY_DEBUG_ENABLED:
                                print(f"  No filtered embeddings available, skipping merge")
                        else:
                            normalized_embeds = filtered_embeds / filtered_embeds.norm(dim=-1, keepdim=True)

                            if MEMORY_DEBUG_ENABLED:
                                print(f"  Filtered embeds shape: {filtered_embeds.shape}")
                                print(f"  Normalized embeds shape: {normalized_embeds.shape}")

                            # Adjust contextual_token_num if needed
                            contextual_token_num = min(contextual_token_num, normalized_embeds.shape[0])
                            if contextual_token_num == 0:
                                if MEMORY_DEBUG_ENABLED:
                                    print(f"  Adjusted contextual tokens to 0, skipping merge")
                            else:
                                # Select contextual tokens evenly spaced
                                target_step = max(1, normalized_embeds.shape[0] // contextual_token_num)
                                target_indices = torch.arange(0, normalized_embeds.shape[0], target_step, device=device)[:contextual_token_num]
                                target_embeds = normalized_embeds[target_indices, :]

                                if MEMORY_DEBUG_ENABLED:
                                    print(f"  Target_step: {target_step}")
                                    print(f"  Target_indices shape: {target_indices.shape}, max: {target_indices.max() if target_indices.shape[0] > 0 else 'N/A'}")
                                    print(f"  Normalized_embeds shape: {normalized_embeds.shape}")

                                # Memory debug: Before similarity computation
                                if MEMORY_DEBUG_ENABLED:
                                    log_memory_stats("VisionZip: Before similarity computation", verbose=True)

                                # Compute similarity for source tokens to targets
                                source_mask = ~torch.isin(torch.arange(normalized_embeds.shape[0], device=device), target_indices)
                                source_embeds = normalized_embeds[source_mask]

                                if MEMORY_DEBUG_ENABLED:
                                    print(f"  Source embeds shape: {source_embeds.shape}")
                                    print(f"  Target embeds shape: {target_embeds.shape}")
                                    print(f"  Expected similarity matrix: {source_embeds.shape[0]} x {target_embeds.shape[0]}")
                                    similarity_memory_gb = (source_embeds.shape[0] * target_embeds.shape[0] * 4) / 1024**3
                                    print(f"  Estimated similarity matrix memory: {similarity_memory_gb:.3f} GB")

                                if source_embeds.shape[0] > 0 and target_embeds.shape[0] > 0:
                                    try:
                                        similarity = torch.matmul(source_embeds, target_embeds.t())

                                        # Memory debug: After similarity computation
                                        if MEMORY_DEBUG_ENABLED:
                                            log_memory_stats("VisionZip: After similarity computation", verbose=True)
                                            log_tensor_info(similarity, "Similarity matrix")

                                    except torch.cuda.OutOfMemoryError as e:
                                        if MEMORY_DEBUG_ENABLED:
                                            print(f"\n{'!'*70}")
                                            print(f"!!! OOM at similarity matrix computation !!!")
                                            print(f"{'!'*70}")
                                            print(f"  Tried to compute: {source_embeds.shape} @ {target_embeds.shape}.T")
                                            log_memory_stats("OOM at similarity", show_tensors=True, verbose=True)
                                        raise e

                                    assign_one_hot = image_embeds.new_zeros(source_embeds.shape[0], contextual_token_num)
                                    assign_one_hot.scatter_(1, similarity.argmax(dim=-1).unsqueeze(-1), 1)
                                    counts = assign_one_hot.sum(dim=0).clamp(min=1).unsqueeze(-1)

                                    # Memory debug: Before aggregation
                                    if MEMORY_DEBUG_ENABLED:
                                        log_memory_stats("VisionZip: Before aggregation", verbose=True)

                                    # Get actual indices in the original image_embeds space
                                    contextual_positions = (~selected_masks).nonzero(as_tuple=True)[0]

                                    if MEMORY_DEBUG_ENABLED:
                                        print(f"  Contextual_positions shape: {contextual_positions.shape}")
                                        print(f"  Target_indices max: {target_indices.max() if target_indices.shape[0] > 0 else 'N/A'}")
                                        print(f"  Source_mask sum: {source_mask.sum()}")

                                    target_positions = contextual_positions[target_indices]
                                    source_positions = contextual_positions[source_mask]

                                    # Mark target tokens as selected
                                    selected_masks[target_positions] = True

                                    try:
                                        # Aggregate source embeddings into targets (use normalized embeddings)
                                        # This matches InternVL3 implementation (line 537)
                                        aggregated_embeds = torch.matmul(assign_one_hot.t(), source_embeds) / counts

                                        # Memory debug: After aggregation
                                        if MEMORY_DEBUG_ENABLED:
                                            log_memory_stats("VisionZip: After aggregation", verbose=True)
                                            print(f"  Aggregated embeds shape: {aggregated_embeds.shape}")

                                    except torch.cuda.OutOfMemoryError as e:
                                        if MEMORY_DEBUG_ENABLED:
                                            print(f"\n{'!'*70}")
                                            print(f"!!! OOM at embedding aggregation !!!")
                                            print(f"{'!'*70}")
                                            log_memory_stats("OOM at aggregation", show_tensors=True, verbose=True)
                                        raise e

                                    image_embeds[target_positions] += aggregated_embeds

                    # Memory debug: VisionZip complete
                    if MEMORY_DEBUG_ENABLED:
                        log_memory_stats("VisionZip: Complete", verbose=True)
                elif self.pruning_method == 'vispruner':
                    important_token_num = int(self.target_visual_token_num * 0.9)
                    diverse_token_num = self.target_visual_token_num - important_token_num

                    image_attns = image_attns.mean(dim=1).mean(dim=0)
                    token_indices = image_attns.argsort(dim=-1, descending=True)

                    important_indices = token_indices[:important_token_num]
                    residual_indices = token_indices[important_token_num:]

                    image_normalized = image_embeds / image_embeds.norm(dim=-1, keepdim=True)
                    while diverse_token_num > 0:
                        residual_embeds = image_normalized[residual_indices]
                        r = min(8, residual_embeds.shape[0] - diverse_token_num)
                        if r <= 0:
                            break

                        a, b = residual_embeds[::2], residual_embeds[1::2]
                        scores = a @ b.t()
                        scores = scores.max(dim=-1).values

                        distinct_indices = scores.argsort(dim=-1, descending=True)[r:]
                        residual_indices = torch.cat([residual_indices[::2][distinct_indices], residual_indices[1::2]])

                    selected_indices = torch.cat([important_indices, residual_indices])
                    selected_masks = torch.zeros(N, dtype=torch.bool, device=device)
                    selected_masks[selected_indices] = True
                elif self.pruning_method == 'dart':
                    pivot_token_num = 8
                    topk_token_num = (self.target_visual_token_num - pivot_token_num) // pivot_token_num
                    pivot_token_step = N // (pivot_token_num + 1)

                    selected_set = set(range(pivot_token_step, N, pivot_token_step))
                    retained_set = set(range(N)) - selected_set
                    image_normalized = image_embeds / image_embeds.norm(dim=-1, keepdim=True)
                    for pivot_idx in list(selected_set):
                        retained_list = list(retained_set)
                        similarity = torch.matmul(image_normalized[pivot_idx], image_normalized[retained_list].t())
                        topk_indices = similarity.topk(topk_token_num, largest=False).indices

                        topk_real_indices = [retained_list[idx] for idx in topk_indices]
                        selected_set.update(topk_real_indices)
                        retained_set.difference_update(topk_real_indices)
                    selected_indices = torch.tensor(list(selected_set), dtype=torch.long, device=device)

                    selected_masks = torch.zeros(N, dtype=torch.bool, device=device)
                    selected_masks[selected_indices] = True
                elif self.pruning_method == 'divprune':
                    # DivPrune: Diversity-based greedy token selection
                    # Reference: InternVL3 implementation (modeling_internvl_chat.py:539-564)
                    # Adapted for Qwen2.5-VL's flat [N, D] format (no batch dimension)

                    image_normalized = image_embeds / image_embeds.norm(dim=-1, keepdim=True)
                    cosine_matrix = 1.0 - torch.matmul(image_normalized, image_normalized.t())  # [N, N]

                    selected_indices = torch.empty(self.target_visual_token_num, dtype=torch.long, device=device)

                    for i in range(self.target_visual_token_num):
                        if i == 0:
                            # Initial selection: token with maximum diversity (2nd smallest cosine distance)
                            # This finds the token that is most different from all others
                            m2 = cosine_matrix  # [N, N]
                            scores = torch.topk(m2, 2, dim=0, largest=False).values[1]  # [N]
                        else:
                            # Subsequent selections: maximize minimum distance to already selected tokens
                            # Select rows corresponding to already selected tokens
                            m2 = cosine_matrix[selected_indices[:i], :]  # [i, N]
                            scores = torch.min(m2, dim=0).values  # [N]

                            # Mask out already selected indices to prevent re-selection
                            scores[selected_indices[:i]] = -float('inf')

                        # Select token with highest diversity score
                        selected_idx = torch.argmax(scores)
                        selected_indices[i] = selected_idx

                    selected_masks = torch.zeros(N, dtype=torch.bool, device=device)
                    selected_masks[selected_indices] = True
                elif self.pruning_method == 'dppruner':
                    image_normalized = image_embeds / image_embeds.norm(dim=-1, keepdim=True)
                    similarity = torch.matmul(image_normalized, image_normalized.t())

                    kernel = similarity

                    cis = kernel.new_zeros((self.target_visual_token_num, N))
                    di2s = torch.diag(kernel)
                    selected_indices = torch.empty(self.target_visual_token_num, dtype=torch.long, device=device)
                    for i in range(self.target_visual_token_num):
                        j = torch.argmin(torch.max(similarity, dim=-1).values) if i==0 else torch.argmax(di2s)
                        # j = torch.argmax(di2s)
                        selected_indices[i] = j

                        eis = (kernel[j, :] - cis[:i, j] @ cis[:i, :]) / torch.sqrt(di2s[j])
                        cis[i, :] = eis
                        di2s -= torch.square(eis)
                        di2s[j] = -float('inf')

                    selected_masks = torch.zeros(N, dtype=torch.bool, device=device)
                    selected_masks[selected_indices] = True
                elif self.pruning_method == 'trim_mean':
                    image_normalized = image_embeds / image_embeds.norm(dim=-1, keepdim=True)
                    text_embeds = inputs_embeds.squeeze(0)[image_token_indices[-1]+2:-5]
                    text_normalized = text_embeds / text_embeds.norm(dim=-1, keepdim=True)

                    similarity = torch.matmul(image_normalized, text_normalized.t()).mean(dim=-1)
                    selected_indices = similarity.topk(self.target_visual_token_num, dim=-1).indices

                    selected_masks = torch.zeros(N, dtype=torch.bool, device=device)
                    selected_masks[selected_indices] = True
                elif self.pruning_method == 'trim_max':
                    image_normalized = image_embeds / image_embeds.norm(dim=-1, keepdim=True)
                    text_embeds = inputs_embeds.squeeze(0)[image_token_indices[-1]+2:-5]
                    text_normalized = text_embeds / text_embeds.norm(dim=-1, keepdim=True)

                    similarity = torch.matmul(image_normalized, text_normalized.t()).max(dim=-1).values
                    selected_indices = similarity.topk(self.target_visual_token_num, dim=-1).indices

                    selected_masks = torch.zeros(N, dtype=torch.bool, device=device)
                    selected_masks[selected_indices] = True
                elif self.pruning_method == 'cdpruner_mean':
                    image_normalized = image_embeds / image_embeds.norm(dim=-1, keepdim=True)
                    similarity = torch.matmul(image_normalized, image_normalized.t())

                    text_embeds = inputs_embeds.squeeze(0)[image_token_indices[-1]+2:-5]
                    text_normalized = text_embeds / text_embeds.norm(dim=-1, keepdim=True)
                    relevance = torch.matmul(image_normalized, text_normalized.t()).mean(dim=-1)
                    relevance = (relevance - relevance.min() + 0.01) / (relevance.max() - relevance.min())

                    kernel = relevance.unsqueeze(1) * similarity * relevance.unsqueeze(0)

                    cis = kernel.new_zeros((self.target_visual_token_num, N))
                    di2s = torch.diag(kernel)
                    selected_indices = torch.empty(self.target_visual_token_num, dtype=torch.long, device=device)
                    for i in range(self.target_visual_token_num):
                        j = torch.argmin(torch.max(similarity, dim=-1).values) if i==0 else torch.argmax(di2s)
                        selected_indices[i] = j

                        eis = (kernel[j, :] - cis[:i, j] @ cis[:i, :]) / torch.sqrt(di2s[j])
                        cis[i, :] = eis
                        di2s -= torch.square(eis)
                        di2s[j] = -float('inf')

                    selected_masks = torch.zeros(N, dtype=torch.bool, device=device)
                    selected_masks[selected_indices] = True
                elif self.pruning_method == 'cdpruner_max':
                    image_normalized = image_embeds / image_embeds.norm(dim=-1, keepdim=True)
                    similarity = torch.matmul(image_normalized, image_normalized.t())

                    text_embeds = inputs_embeds.squeeze(0)[image_token_indices[-1]+2:-5]
                    text_normalized = text_embeds / text_embeds.norm(dim=-1, keepdim=True)
                    relevance = torch.matmul(image_normalized, text_normalized.t()).max(dim=-1).values
                    relevance = (relevance - relevance.min() + 0.01) / (relevance.max() - relevance.min())

                    kernel = relevance.unsqueeze(1) * similarity * relevance.unsqueeze(0)

                    cis = kernel.new_zeros((self.target_visual_token_num, N))
                    di2s = torch.diag(kernel)
                    selected_indices = torch.empty(self.target_visual_token_num, dtype=torch.long, device=device)
                    for i in range(self.target_visual_token_num):
                        j = torch.argmin(torch.max(similarity, dim=-1).values) if i==0 else torch.argmax(di2s)
                        selected_indices[i] = j

                        eis = (kernel[j, :] - cis[:i, j] @ cis[:i, :]) / torch.sqrt(di2s[j])
                        cis[i, :] = eis
                    di2s -= torch.square(eis)
                    di2s[j] = -float('inf')

                    selected_masks = torch.zeros(N, dtype=torch.bool, device=device)
                    selected_masks[selected_indices] = True
                elif self.pruning_method == 'sparsevlm':
                    selected_masks = torch.ones(N, dtype=torch.bool, device=device)
                elif self.pruning_method == 'tops_variant3':
                    # TOPS-Variant3: Adaptive Two-Stage Text-Concept Hierarchical Pruning
                    print(f"\n{'='*80}")
                    print(f"TOPS-Variant3 Stage 1: THCP (Text-Concept Hierarchical Pruning)")
                    print(f"{'='*80}")

                    # Extract text embeddings from inputs_embeds
                    image_token_indices = (input_ids == self.config.image_token_id).nonzero(as_tuple=True)[1]
                    if len(image_token_indices) > 0:
                        image_token_end = image_token_indices[-1].item()
                        # Extract text tokens after image tokens (exclude last 5 tokens for padding/eos)
                        text_start_idx = image_token_end + 1
                        text_end_idx = input_ids.shape[1] - 5

                        if text_start_idx < text_end_idx:
                            text_embeds = inputs_embeds.squeeze(0)[text_start_idx:text_end_idx]
                        else:
                            text_embeds = torch.tensor([], device=device)
                    else:
                        text_embeds = torch.tensor([], device=device)

                    M = text_embeds.shape[0]

                    # Fallback to attention-based if no text
                    if M == 0:
                        print("[TOPS-Variant3 Warning] No text embeddings found, using attention fallback")
                        image_attns = image_attns.mean(dim=1).mean(dim=0)
                        selected_indices = image_attns.topk(self.target_visual_token_num, dim=-1).indices
                        selected_masks = torch.zeros(N, dtype=torch.bool, device=device)
                        selected_masks[selected_indices] = True
                    else:
                        # Adaptive Stage 1: keep target × 2 tokens (relevance-only)
                        stage1_keep_num = max(1, self.target_visual_token_num * 2)
                        tokens_to_select = min(stage1_keep_num, N)

                        print(f"  Visual tokens: {N}")
                        print(f"  Text tokens: {M}")
                        print(f"  Target (final): {self.target_visual_token_num}")
                        print(f"  Stage 1 target: {tokens_to_select} (adaptive: target × 2)")
                        print(f"  Mode: Relevance")

                        # Normalize embeddings
                        image_normalized = image_embeds / (image_embeds.norm(dim=-1, keepdim=True) + 1e-8)
                        text_normalized = text_embeds / (text_embeds.norm(dim=-1, keepdim=True) + 1e-8)

                        # Relevance scores averaged across text tokens when M > 1
                        response_matrix = torch.matmul(image_normalized, text_normalized.t())  # (N, M)
                        if M > 1:
                            text_relevance = response_matrix.mean(dim=-1)
                        else:
                            text_relevance = response_matrix.squeeze(-1)

                        text_relevance = (text_relevance - text_relevance.min()) / (
                            (text_relevance.max() - text_relevance.min()) + 1e-6
                        )

                        visual_similarity = torch.matmul(image_normalized, image_normalized.t())
                        available_mask = torch.ones(N, dtype=torch.bool, device=device)
                        selected_indices: List[int] = []

                        relevance_weight = 0.5
                        diversity_weight = 0.5

                        for step in range(tokens_to_select):
                            if not available_mask.any():
                                break

                            scores = text_relevance.clone()
                            if step > 0:
                                selected_tensor = torch.tensor(selected_indices, device=device, dtype=torch.long)
                                max_similarity_to_selected = visual_similarity[:, selected_tensor].max(dim=1).values
                                diversity_scores = 1 - max_similarity_to_selected
                                scores = relevance_weight * scores + diversity_weight * diversity_scores

                            scores[~available_mask] = -float('inf')
                            selected_idx = scores.argmax().item()
                            selected_indices.append(selected_idx)
                            available_mask[selected_idx] = False

                        if len(selected_indices) == 0:
                            selected_indices = list(range(tokens_to_select))

                        selected_tensor = torch.tensor(selected_indices, device=device, dtype=torch.long)
                        selected_masks = torch.zeros(N, dtype=torch.bool, device=device)
                        selected_masks[selected_tensor] = True

                        print(f"[TOPS-Variant3 Stage1] selected_masks.sum = {selected_masks.sum().item()}")

                        print(f"  Selected {selected_masks.sum().item()} visual tokens")
                        print(f"{'='*80}\n")

                self.visual_token_len = selected_masks.sum().item()

                n_image_tokens = (input_ids == self.config.image_token_id).sum().item()
                n_image_features = image_embeds.shape[0]
                if n_image_tokens != n_image_features:
                    raise ValueError(
                        f"Image features and image tokens do not match: tokens: {n_image_tokens}, features {n_image_features}"
                    )

                mask = input_ids == self.config.image_token_id
                mask_unsqueezed = mask.unsqueeze(-1)
                mask_expanded = mask_unsqueezed.expand_as(inputs_embeds)
                image_mask = mask_expanded.to(inputs_embeds.device)

                image_embeds = image_embeds.to(inputs_embeds.device, inputs_embeds.dtype)
                inputs_embeds = inputs_embeds.masked_scatter(image_mask, image_embeds)

            if pixel_values_videos is not None:
                pixel_values_videos = pixel_values_videos.type(self.visual.dtype)
                video_embeds = self.visual(pixel_values_videos, grid_thw=video_grid_thw)
                n_video_tokens = (input_ids == self.config.video_token_id).sum().item()
                n_video_features = video_embeds.shape[0]
                if n_video_tokens != n_video_features:
                    raise ValueError(
                        f"Video features and video tokens do not match: tokens: {n_video_tokens}, features {n_video_features}"
                    )

                mask = input_ids == self.config.video_token_id
                mask_unsqueezed = mask.unsqueeze(-1)
                mask_expanded = mask_unsqueezed.expand_as(inputs_embeds)
                video_mask = mask_expanded.to(inputs_embeds.device)

                video_embeds = video_embeds.to(inputs_embeds.device, inputs_embeds.dtype)
                inputs_embeds = inputs_embeds.masked_scatter(video_mask, video_embeds)

            if attention_mask is not None:
                attention_mask = attention_mask.to(inputs_embeds.device)

        # if we get 4D attention mask we cannot calculate rope deltas anymore. TODO @raushan fixme
        if position_ids is None and (attention_mask is None or attention_mask.ndim == 2):
            # calculate RoPE index once per generation in the pre-fill stage only
            if (
                (cache_position is not None and cache_position[0] == 0)
                or self.rope_deltas is None
                or (past_key_values is None or past_key_values.get_seq_length() == 0)
            ):
                position_ids, rope_deltas = self.get_rope_index(
                    input_ids,
                    image_grid_thw,
                    video_grid_thw,
                    second_per_grid_ts,
                    attention_mask,
                )
                self.rope_deltas = rope_deltas

                # Select visual tokens using `selected_masks`
                if selected_masks.sum() < selected_masks.numel():
                    system_prompt_length = int(mask.max(dim=-1).indices)
                    visual_token_length = selected_masks.shape[0]
                    visual_token_indices = selected_masks.nonzero().squeeze(-1)
                    retain_token_indices = torch.cat((
                        torch.arange(system_prompt_length, device=device),
                        visual_token_indices + system_prompt_length,
                        torch.arange(system_prompt_length+visual_token_length, inputs_embeds.shape[1], device=device),
                    ))
                    print(f"[TOPS-Variant3 Stage1] retain_token_indices length = {retain_token_indices.shape[0]}")
                    self.retain_token_indices = retain_token_indices

                    inputs_embeds = inputs_embeds[:, retain_token_indices]
                    position_ids = position_ids[:, :, retain_token_indices]
                    attention_mask = attention_mask[:, retain_token_indices]
                    cache_position = cache_position[:retain_token_indices.shape[0]]

            # then use the prev pre-calculated rope-deltas to get the correct position ids
            else:
                batch_size, seq_length, _ = inputs_embeds.shape
                delta = (
                    (cache_position[0] + self.rope_deltas).to(inputs_embeds.device)
                    if cache_position is not None
                    else 0
                )
                position_ids = torch.arange(seq_length, device=inputs_embeds.device)
                position_ids = position_ids.view(1, -1).expand(batch_size, -1)
                if cache_position is not None:  # otherwise `deltas` is an int `0`
                    delta = delta.repeat_interleave(batch_size // delta.shape[0], dim=0)
                position_ids = position_ids.add(delta)
                position_ids = position_ids.unsqueeze(0).expand(3, -1, -1)

                # Modify the attention mask in the decode stage
                if attention_mask is not None and hasattr(self, 'retain_token_indices'):
                    self.retain_token_indices = torch.cat((
                        self.retain_token_indices,
                        self.retain_token_indices.new_ones(1) * (attention_mask.shape[1] - 1),
                    ))
                    attention_mask = attention_mask[:, self.retain_token_indices]

        outputs = self.model(
            input_ids=None,
            position_ids=position_ids,
            attention_mask=attention_mask,
            past_key_values=past_key_values,
            inputs_embeds=inputs_embeds,
            use_cache=use_cache,
            output_attentions=output_attentions,
            output_hidden_states=output_hidden_states,
            return_dict=return_dict,
            cache_position=cache_position,
        )

        hidden_states = outputs[0]
        logits = self.lm_head(hidden_states)

        loss = None
        if labels is not None:
            # Upcast to float if we need to compute the loss to avoid potential precision issues
            logits = logits.float()
            # Shift so that tokens < n predict n
            shift_logits = logits[..., :-1, :].contiguous()
            shift_labels = labels[..., 1:].contiguous()
            # Flatten the tokens
            loss_fct = CrossEntropyLoss()
            shift_logits = shift_logits.view(-1, self.config.vocab_size)
            shift_labels = shift_labels.view(-1)
            # Enable model parallelism
            shift_labels = shift_labels.to(shift_logits.device)
            loss = loss_fct(shift_logits, shift_labels)

        if not return_dict:
            output = (logits,) + outputs[1:]
            return (loss,) + output if loss is not None else output

        return Qwen2_5_VLCausalLMOutputWithPast(
            loss=loss,
            logits=logits,
            past_key_values=outputs.past_key_values,
            hidden_states=outputs.hidden_states,
            attentions=outputs.attentions,
            rope_deltas=self.rope_deltas,
        )
